#include <cstdio>
#include <vector>

int main() {
    int n;
    long long t;
    scanf("%d %lld", &n, &t);
    std::vector<long long> a(n);
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);

    int l = 0, r = n - 1;
    while (l < r) {
        long long s = a[l] + a[r];
        if (s == t) break;
        else if (s < t) ++l;
        else --r;
    }
    printf("%d %d\n", l + 1, r + 1);
    return 0;
}
